(function(){
  const particles = [];
  const N = 130;
  for(let i=0;i<N;i++){
    const edge = Math.random()<0.5;
    let y;
    if(edge) y = Math.random()*H()*0.3; else y = H()*0.7+Math.random()*H()*0.3;
    particles.push({
      x: Math.random()*W(),
      y: y,
      baseY: y,
      r: 0.5+Math.random()*2.0,
      speed: 0.04+Math.random()*0.12,
      drift: (Math.random()-0.5)*0.25,
      phase: Math.random()*Math.PI*2,
      flicker: 0.5+Math.random()*1.5,
      color: PALETTE[Math.floor(Math.random()*PALETTE.length)]
    });
  }
  const threads=[];
  for(let i=0;i<7;i++){
    threads.push({
      x: Math.random()*W(),
      y: Math.random()<0.5? Math.random()*H()*0.22 : H()*0.78+Math.random()*H()*0.22,
      len: 50+Math.random()*110,
      angle: Math.random()*Math.PI*2,
      speed:0.002+Math.random()*0.004,
      opacity:0.12+Math.random()*0.18
    });
  }

  let t=0;
  function frame(){
    t+=1;
    ctx.clearRect(0,0,W(),H());

    threads.forEach(th=>{
      th.angle+=th.speed;
      const x2 = th.x+Math.cos(th.angle)*th.len;
      const y2 = th.y+Math.sin(th.angle)*th.len;
      const grad = ctx.createLinearGradient(th.x,th.y,x2,y2);
      grad.addColorStop(0,'rgba(255,255,255,0)');
      grad.addColorStop(0.5,`rgba(255,255,255,${th.opacity})`);
      grad.addColorStop(1,'rgba(255,255,255,0)');
      ctx.strokeStyle=grad;
      ctx.lineWidth=1;
      ctx.beginPath();
      ctx.moveTo(th.x,th.y);
      ctx.lineTo(x2,y2);
      ctx.stroke();
    });

    particles.forEach(p=>{
      p.y += p.speed;
      p.x += Math.sin(t*0.01+p.phase)*p.drift;
      if(p.y>p.baseY+35) p.y=p.baseY-35;
      const flick = 0.35+0.65*Math.abs(Math.sin(t*0.02*p.flicker+p.phase));
      ctx.beginPath();
      ctx.fillStyle=p.color;
      ctx.globalAlpha = flick*0.75;
      ctx.shadowBlur=6;
      ctx.shadowColor=p.color;
      ctx.arc(p.x,p.y,p.r,0,Math.PI*2);
      ctx.fill();
    });
    ctx.globalAlpha=1;
    ctx.shadowBlur=0;
    requestAnimationFrame(frame);
  }
  frame();
})();
